PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord ?polarityValue ?polarityLabel
WHERE {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord ;
                  dcterms:isPartOf <http://liita.it/data/id/lemma/LemmaBank> .

    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .
    ?polarity rdfs:label ?polarityLabel .
    FILTER(STR(?polarityLabel) = "Negative")

    ?translationEntry ontolex:canonicalForm ?italianLemma ;
                      vartrans:translatableAs ?parmigianoLexEntry .

    ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                      ontolex:writtenRep ?parmigianoWord .
}
ORDER BY ?polarityValue

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion elita:Gioia .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?emotionLabel ?pos (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  lila:hasPOS ?pos .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
}
GROUP BY ?emotionLabel ?pos
ORDER BY DESC(?count)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT (COUNT(DISTINCT ?dialectLexEntry) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
    FILTER(STR(?emotionLabel) = "Rabbia")
  }

  ?translationEntry ontolex:canonicalForm ?italianLemma ;
                    vartrans:translatableAs ?dialectLexEntry .
  ?dialectLexEntry ontolex:canonicalForm ?dialectLemma .
  ?dialectLemma dcterms:isPartOf ?dialectLemmaBank ;
                ontolex:writtenRep ?dialectWord .
  FILTER(regex(str(?dialectLemmaBank), "Dialetto", "i"))
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?pos ?emotionLabel (COUNT(DISTINCT ?dialectWord) AS ?count)
WHERE {
    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      lila:hasPOS ?pos ;
                      ontolex:writtenRep ?italianWord .
    }

    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
    }

    ?translationEntry ontolex:canonicalForm ?italianLemma ;
                      vartrans:translatableAs ?dialectLexEntry .

    ?dialectLexEntry ontolex:canonicalForm ?dialectLemma .
    ?dialectLemma dcterms:isPartOf ?dialectLemmaBank ;
                  ontolex:writtenRep ?dialectWord .

    FILTER(regex(str(?dialectLemmaBank), "Dialetto", "i"))
}
GROUP BY ?pos ?emotionLabel
ORDER BY ?pos ?emotionLabel

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?wholeWord ?partWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?wholeEntry ontolex:canonicalForm [ ontolex:writtenRep ?wholeWord ] ;
                ontolex:sense ?wholeSense .
    FILTER(STR(?wholeWord) = "edificio")

    ?partSense lexinfo:partMeronym ?wholeSense .
    ?partEntry ontolex:sense ?partSense ;
               ontolex:canonicalForm [ ontolex:writtenRep ?partWord ] .

    OPTIONAL { ?partSense skos:definition ?definition }
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?italianWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense ?sense .
    FILTER(STR(?writtenRep) = "strumento")

    ?partSense lexinfo:partMeronym ?sense .
    ?partEntry ontolex:sense ?partSense .

    OPTIONAL { ?partSense skos:definition ?definition }
  }

  ?partEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord .
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT ?hypernymWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    FILTER ( STR(?writtenRep) = "veicolo" ) .

    ?word ontolex:sense ?sense .
    ?sense lexinfo:hyponym ?hyperSense .

    ?hyperWord ontolex:sense ?hyperSense ;
               ontolex:canonicalForm [ ontolex:writtenRep ?hypernymWord ] .
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT ?writtenRep ?sense ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense ?sense .
    ?sense skos:definition ?definition .
    FILTER(STR(?writtenRep) = "casa")
  }
}

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?sense ?definition
WHERE {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
              ontolex:sense ?sense .
        ?sense skos:definition ?definition .
        FILTER(STR(?writtenRep) = "acqua")
    }
}
ORDER BY ?sense

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?italianWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense [ skos:definition ?definition ] .
    FILTER(REGEX(?definition, "luce", "i"))
  }
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord ?definition ?emotionLabel ?polarityValue
WHERE {
    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      lila:hasPOS lila:verb ;
                      ontolex:writtenRep ?italianWord .
    }

    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarityValue ?polarityValue .
    FILTER(?polarityValue > 0.9)

