    { ?sense lexinfo:approximateSynonym ?relatedSense . }
    UNION
    { ?relatedSense lexinfo:approximateSynonym ?sense . }

    ?relatedWord ontolex:sense ?relatedSense .
  }

  ?relatedWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord .
  }
}

